class Solution {
public:
    int sumCounts(vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                unordered_set<int> s(nums.begin() + i, nums.begin() + j + 1);
                ans += (long long)s.size() * s.size();
            }
        return (int)ans;
    }
};

