class Solution {
    public int sumCounts(int[] nums) {
        int n = nums.length;
        long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                Set<Integer> s = new HashSet<>();
                for (int k = i; k <= j; k++) s.add(nums[k]);
                ans += (long) s.size() * s.size();
            }
        return (int) ans;
    }
};

